    H,W=len(i),len(i[0])
    cnts={v:sum(row.count(v) for row in i) for row in i for v in row}
    bg=max(cnts,key=cnts.get)
    S=[(r,c) for r in range(H) for c in range(W) if i[r][c]!=bg]
    dirs4=((1,0),(-1,0),(0,1),(0,-1))
    seen=set(S); q=list(S)
    while q:
        r,c=q.pop()
        for dr,dc in dirs4:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and i[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
        for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and i[nr][nc]==bg and (nr,nc) not in seen:
