import numpy as np,collections
def resmajor(i, outshape):
    i=np.array(i); H,W=i.shape; oh,ow=outshape
    res={}
    # try all offsets and see if a consistent tile exists: for each (r%dr, c%dc) take majority over cells
    best=[]
    for dr in range(1,H+1):
        for dc in range(1,W+1):
            if H/dr==oh and W/dc==ow and H%dr==0 and W%dc==0: continue
            cnt=collections.defaultdict(collections.Counter)
            for r in range(H):
                for c in range(W):
                    cnt[(r%dr,c%dc)][i[r,c]]+=1
            tile=[[cnt[k].most_common(1)[0][0] for k in range(dc)] for k in range(dr)]
            if tile==[[int(x) for x in row] for row in outshape] if False else True: pass
            score=sum(1 for r in range(H) for c in range(W) if i[r,c]==tile[r%dr][c%dc])
            best.append((score,dr,dc,tile))
    best.sort(reverse=True)
    return best[:3]
